sysevent_script_action.script:
var gr = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
gr.get(current.target_trade_case);
// MSSRBXCE - 522 : Commenting out if else condition,  outcome should be set as client response for all conditions
/*
if(gr.trade_status.getDisplayValue() == 'Trade Unmatched ' && current.client_response == 'Client Disagree'){
	gr.swb_widget_outcome = 'Trade Not Recognised';
}else{
gr.swb_widget_outcome = current.client_response;
}
*/
gr.swb_widget_outcome = current.client_response;

//MSSRBXCE-441 Commented out the below two if conditions as 'Email handler' field was getting updated on 'SWB Widget Outcome' response. Hence not required.
/*if (current.client_response == 'Client Disagree')
    gr.email_handler_outcome = 'Disagree';
if (current.client_response == 'Client Agree')
    gr.email_handler_outcome = 'Agree';
//MSSRBXCE-390-470 Modify for Trade Unmatched scenario
if (current.client_response == 'Shape Difference')
    gr.email_handler_outcome = 'Shape Difference';
if (current.client_response == 'Other Issue')
    gr.email_handler_outcome = 'Other issue';*/
gr.swb_payload = current.payload;

//MSSRBXCE-307-366 Extract Client Comments from swb payload 
var finalPayload=current.payload.slice(1,-1);
if (finalPayload.indexOf('Comment_Client') > -1) {
    var jsonObj = JSON.parse(finalPayload);
    gr.client_comments = jsonObj.Comment_Client;
}

gr.update();
